### FUNCION: handleCellClick
```javascript
/**
 * Maneja el click en cualquier celda de la hoja de cálculo para seleccionar el elemento
 * y mostrar/actualizar los controles de color.
 * @param {Event} e - El evento de click.
 */
function handleCellClick(e) {
    // 1. Identificar si se hizo clic en una celda editable
    const target = e.target.closest('[contenteditable="true"]');

    if (!target) {
        // Si no se hizo clic en una celda de datos, ocultar los controles.
        document.getElementById('color-controls').classList.add('hidden');
        return;
    }

    // 2. Determinar la celda activa (la que debe recibir el color)
    let activeCell = target;

    // 3. Mostrar y configurar los controles de color
    const colorControls = document.getElementById('color-controls');
    if (!colorControls) return; // Safety check

    colorControls.classList.remove('hidden');

    // Obtener el color actual del fondo para preseleccionar el input type="color"
    let currentColor = activeCell.style.backgroundColor || '#ffffff';
    document.getElementById('color-picker-input').value = currentColor;


    // 4. Añadir listeners temporales para la lógica de aplicación de color
    const applyButton = document.getElementById('apply-color-btn');

    // Limpiar listeners anteriores para evitar duplicados
    applyButton.onclick = null;

    applyButton.onclick = function() {
        const selectedColor = document.getElementById('color-picker-input').value;
        activeCell.style.backgroundColor = selectedColor;
        // Opcional: Si el color aplicado es un fondo, se podría querer resetear otros estilos (como los de hover).
    };
}
```

