function handleColumnSelection(event) {
    const target = event.target;
    if (!target || !target.classList.contains('col-header')) return;

    // Deseleccionar cualquier columna previamente seleccionada y limpiar estilos/controles temporales
    document.querySelectorAll('.col-header[data-selected="true"]').forEach(el => {
        el.removeAttribute('data-selected');
        el.style.backgroundColor = ''; // Limpiar color de fondo
        el.style.cursor = 'pointer';
    });

    const columnLetter = target.dataset.column;

    if (!columnLetter) return;

    // 1. Marcar la columna seleccionada
    target.setAttribute('data-selected', 'true');
    target.style.backgroundColor = '#e0f7fa'; // Color de selección visual
    target.style.cursor = 'pointer';

    console.log(`Columna ${columnLetter} seleccionada.`);

    // 2. Mostrar/activar controles (Simulación: se pueden añadir botones o un menú aquí)
