### FUNCION: deleteColumn
```javascript
function deleteColumn(columnLetter) {
    if (!confirm(`¿Está seguro de que desea eliminar permanentemente la columna ${columnLetter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    const columnHeader = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');

    // 1. Eliminar la cabecera de la columna (<th> en thead)
    if (columnHeader) {
        columnHeader.remove();
    } else {
        console.warn(`No se encontró el encabezado para la columna ${columnLetter}.`);
        return;
    }

    // 2. Eliminar las celdas de datos correspondientes en cada fila (<td> en tbody)
    rows.forEach(row => {
        // Encontrar y eliminar la celda específica dentro de esa fila
        const cellToDelete = row.querySelector(`[data-cell^="${columnLetter}"]`);
        if (cellToDelete) {
            cellToDelete.remove();
        }
    });

    console.log(`Columna ${columnLetter} eliminada exitosamente.`);
}
```

