                 // Limpiamos el contenido si era solo un valor numérico sin formato de celda
                 this.textContent = content;
            }
        });

        // Opcionalmente, un listener 'focus' para resaltar visualmente la celda al hacer clic (si se requiere).
        cell.addEventListener('focus', function() {
            this.classList.add('focused-cell'); // Asumiendo que styles.css tiene una clase .focused-cell
        });
    });

    // Listener global para limpiar el foco visual cuando se haga clic en cualquier parte del documento (fuera de las celdas).
    document.body.addEventListener('click', function(e) {
        if (!e.target.closest('[contenteditable="true"]')) {
            dataCells.forEach(c => c.classList.remove('focused-cell'));
        }
    });
}

// Función para manejar la selección de columnas (clic en el encabezado A, B, C...)
function handleColumnSelection(event) {
    const target = event.target;
    if (!target || !target.classList.contains('col-header')) return;

    // Deseleccionar cualquier columna previamente seleccionada y limpiar estilos/controles temporales
    document.querySelectorAll('.col-header[data-selected="true"]').forEach(el => {
        el.removeAttribute('data-selected');
        el.style.backgroundColor = ''; // Limpiar color de fondo
        el.style.cursor = 'pointer';
    });

    const columnLetter = target.dataset.column;

    if (!columnLetter) return;

    // 1. Marcar la columna seleccionada
    target.setAttribute('data-selected', 'true');
    target.style.backgroundColor = '#e0f7fa'; // Color de selección visual
    target.style.cursor = 'pointer';

    console.log(`Columna ${columnLetter} seleccionada.`);

    // Aquí se podría invocar un panel de control visible si existiera en el HTML
}

// Función para limpiar el contenido de una columna específica
function clearColumnContent(columnLetter) {
    const dataCells = document.querySelectorAll(`[data-cell^="${columnLetter}"]`);
    let count = 0;
    dataCells.forEach(cell => {
        // Resetear contenido y estilos (excepto el de la tabla)
        cell.textContent = '';
        cell.style.backgroundColor = ''; // Asegurar que no haya color residual
        count++;
    });
    console.log(`Contenido de la columna ${columnLetter} limpiado en ${count} celdas.`);
}

// Función para cambiar el fondo de todas las celdas de una columna específica
function changeColumnBackgroundColor(columnLetter) {
    const dataCells = document.querySelectorAll(`[data-cell^="${columnLetter}"]`);
    let count = 0;
    const color = '#fff3e0'; // Color de fondo suave para destacar la selección

    dataCells.forEach(cell => {
        // Aplicar el nuevo color de fondo a todas las celdas de esta columna
        cell.style.backgroundColor = color;
        count++;
    });
    console.log(`Fondo de la columna ${columnLetter} cambiado a ${color} en ${count} celdas.`);
}

// Función para eliminar una columna completa
function deleteColumn(columnLetter) {
    if (!confirm(`¿Está seguro de que desea eliminar permanentemente la columna ${columnLetter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    const columnHeader = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');

    // 1. Eliminar la cabecera de la columna (<th> en thead)
    if (columnHeader) {
        columnHeader.remove();
    } else {
        console.warn(`No se encontró el encabezado para la columna ${columnLetter}.`);
        return;
    }

    // 2. Eliminar las celdas de datos correspondientes en cada fila (<td> en tbody)
    rows.forEach(row => {
        // Encontrar y eliminar la celda específica dentro de esa fila
        const cellToDelete = row.querySelector(`[data-cell^="${columnLetter}"]`);
        if (cellToDelete) {
            cellToDelete.remove();
        }
    });

    console.log(`Columna ${columnLetter} eliminada exitosamente.`);
}


// Función principal que arranca la aplicación
function startApp() {
    initializeCellEditing();

    // Añadir el listener de selección a todos los encabezados de columna
    document.querySelectorAll('.col-header').forEach(header => {
        header.addEventListener('click', handleColumnSelection);
    });
}

startApp();
