### FUNCION: deleteColumn
```js
function deleteColumn() {
    const selectedHeader = document.querySelector('.col-header.selected');
    if (!selectedHeader) return;

    const columnLetter = selectedHeader.dataset.column;
    const columnIndex = Array.from(document.querySelectorAll('.col-header')).indexOf(selectedHeader);

    // Confirmación simple de eliminación
    if (!confirm(`¿Está seguro que desea borrar la columna ${columnLetter}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Eliminar el encabezado de la columna (th en thead)
    selectedHeader.remove();
    const headerRow = selectedHeader.closest('tr');
    headerRow.removeChild(selectedHeader); // Esto asegura que solo se elimina el TH del THead

    // 2. Iterar sobre cada fila y eliminar la celda de datos correspondiente (td en tbody)
    const dataRows = document.querySelectorAll('#spreadsheet-grid tbody tr');
    dataRows.forEach(row => {
        // En una tabla bien estructurada, el índice de columna corresponde al índice del TH/TD.
        // Como ya eliminamos el TH, debemos buscar la celda en la posición correcta (columnIndex)
        const cells = Array.from(row.querySelectorAll('td'));
        if (cells[columnIndex]) {
            cells[columnIndex].remove();
        }
    });

    // 3. Limpiar controles y resetear selección visual
    document.getElementById('column-controls').style.display = 'none';
    document.querySelectorAll('.col-header').forEach(h => h.classList.remove('selected'));
    document.getElementById('selected-column-letter').textContent = 'N/A';

    // Reaplicar el listener en caso de que se haya perdido o para asegurar la reactividad (aunque no debería ser necesario aquí)
    initializeColumnListeners();
}
