### FUNCION: deleteColumn
```js
function deleteColumn(columnLetter) {
    if (!confirm(`¡ADVERTENCIA! ¿Está seguro de que desea ELIMINAR permanentemente la columna ${columnLetter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    // 1. Obtener todos los elementos TD que pertenecen a esta columna
    const columnCells = Array.from(document.querySelectorAll(`td[data-cell^="${columnLetter}"]`));

    if (columnCells.length === 0) return;

    // 2. Eliminar las celdas de datos (TDs) en el tbody
    columnCells.forEach(cell => {
        // El padre inmediato es la fila TR
        const row = cell.closest('tr');
        if (row) {
            row.removeChild(cell);
        }
    });

    // 3. Eliminar el encabezado de columna (TH) del thead
    const headerCell = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (headerCell && headerCell.parentNode) {
        headerCell.parentNode.removeChild(headerCell);
    }

    // 4. Limpiar controles de la interfaz
    document.getElementById('column-controls').style.display = 'none';
    document.getElementById('column-controls').innerHTML = '';
}
