### FUNCION: handleColumnHeaderClick
```javascript
function handleColumnHeaderClick(event) {
    const target = event.target;
    if (!target || !target.classList.contains('col-header')) return;

    // Obtener la letra de la columna (ej: 'A')
    let columnLetter = '';
    const headerText = target.textContent.trim();
    if (headerText.match(/^[A-Z]+$/)) {
        columnLetter = headerText;
    } else {
        console.error("Elemento de encabezado no identificado.");
        return;
    }

    // 1. Limpiar cualquier menú activo previo
    document.querySelectorAll('.column-menu').forEach(el => el.remove());

    // 2. Crear y mostrar el menú contextual
    const menu = document.createElement('div');
    menu.className = 'column-menu';
    menu.style.position = 'absolute';
    menu.style.top = `${event.pageY}px`;
    menu.style.left = `${event.pageX}px`;
    menu.style.background = 'white';
    menu.style.border = '1px solid #ccc';
    menu.style.boxShadow = '2px 2px 5px rgba(0,0,0,0.2)';
    menu.style.zIndex = '1000';

    const options = [
        { text: 'Cambiar Fondo de Color', action: () => { /* Se requiere selección de color */ } },
        { text: 'Borrar Contenido', action: () => clearColumnContent(columnLetter) },
        { text: 'Eliminar Columna', action: () => deleteColumn(columnLetter) }
    ];

    let menuHTML = `<h4>Menú de opciones para la columna ${columnLetter}:</h4>`;
    options.forEach(opt => {
        menuHTML += `<button class="col-option" data-action="${opt.text}">${opt.text}</button>`;
    });

    menu.innerHTML = menuHTML;
    document.body.appendChild(menu);

    // 3. Añadir listeners a los botones del menú
    const buttons = menu.querySelectorAll('.col-option');
    buttons.forEach(button => {
        button.addEventListener('click', (e) => {
            const actionText = e.target.getAttribute('data-action');

            if (actionText === 'Cambiar Fondo de Color') {
                // Para la prueba, simulamos el requerimiento mostrando un selector básico o llamando a una función que lo maneje.
                alert("Seleccione el color de fondo para la columna " + columnLetter);
                const selectedColor = prompt("Ingrese el código de color (ej: #ff0000):", "#ff0000");
                if (selectedColor) {
                    applyBackgroundColor(columnLetter, selectedColor);
                }
            } else if (actionText === 'Borrar Contenido') {
                clearColumnContent(columnLetter);
            } else if (actionText === 'Eliminar Columna') {
                if (confirm(`¿Está seguro de que desea eliminar la columna ${columnLetter}? Esta acción es irreversible.`)) {
                    deleteColumn(columnLetter);
                }
            }

            // Ocultar y remover el menú después de seleccionar una opción
            menu.remove();
        });
    });

    // 4. Cerrar el menú al hacer clic fuera
    document.addEventListener('click', (e) => {
        if (!menu.contains(e.target)) {
            menu.remove();
        }
    });
}
