function initializeRowSelectionAndControls() {
    const rowHeaders = document.querySelectorAll('.row-header');
    const bodyRows = document.querySelectorAll('.data-row');
    const controlsPanel = document.querySelector('.controls-panel');
    const clearBtn = document.getElementById('btn-clear-row');
    const colorBtn = document.getElementById('btn-color-row');
    const deleteBtn = document.getElementById('btn-delete-row');

    let selectedRow = null;

    // Function to handle row selection logic
    function selectRow(event) {
        const header = event.currentTarget;
        selectedRow = header.closest('.data-row');

        if (selectedRow) {
            // Deselect any previously selected row
            document.querySelectorAll('.data-row').forEach(row => {
                row.classList.remove('selected-row');
                Array.from(row.querySelectorAll('td')).forEach(cell => {
                    cell.style.backgroundColor = ''; // Reset background color
                });
            });

            // Select the new row
            selectedRow.classList.add('selected-row');
            Array.from(selectedRow.querySelectorAll('td')).forEach(cell => {
                cell.style.backgroundColor = '#fff'; // Highlight selected cells (assuming white default)
            });

            // Enable controls
            clearBtn.disabled = false;
            colorBtn.disabled = false;
            deleteBtn.disabled = false;
        } else {
            selectedRow = null;
            Array.from(document.querySelectorAll('.data-row')).forEach(row => {
                row.classList.remove('selected-row');
                Array.from(row.querySelectorAll('td')).forEach(cell => {
                    cell.style.backgroundColor = ''; // Reset background color
                });
            });
            // Disable controls if no row is selected (though this shouldn't happen with current setup)
            clearBtn.disabled = true;
            colorBtn.disabled = true;
            deleteBtn.disabled = true;
        }
    }

    // Attach selection listener to all row headers
    rowHeaders.forEach(header => {
        header.addEventListener('click', selectRow);
    });

    // --- Control Panel Event Listeners ---

    // 1. Clear Content
    clearBtn.addEventListener('click', () => {
        if (selectedRow) {
            const cells = selectedRow.querySelectorAll('td');
            cells.forEach(cell => {
                cell.textContent = '';
                cell.style.backgroundColor = '#fff'; // Reset color after clearing
            });
        }
    });

    // 2. Change Background Color
    colorBtn.addEventListener('click', () => {
        if (selectedRow) {
            const cells = selectedRow.querySelectorAll('td');
            const newColor = prompt("Ingrese el color de fondo deseado (ej: #cccccc, red):", '#ffffcc');
            if (newColor) {
                cells.forEach(cell => {
                    cell.style.backgroundColor = newColor;
                });
            }
        }
    });

    // 3. Delete Row
    deleteBtn.addEventListener('click', () => {
        if (selectedRow && confirm(`¿Está seguro de que desea eliminar la fila ${selectedRow.dataset.row}?`)) {
            selectedRow.classList.remove('selected-row');
            selectedRow.remove();
            // Reset controls after deletion
            clearBtn.disabled = true;
            colorBtn.disabled = true;
            deleteBtn.disabled = true;
        }
    });
}
