/**
 * Inicializa la funcionalidad de selección de filas y los controles asociados (borrar, limpiar, cambiar color).
 */
function initializeRowSelectionAndControls() {
    const rowHeaders = document.querySelectorAll('.row-header');
    let selectedRow = null;

    // Helper para deseleccionar cualquier fila previamente seleccionada y limpiar controles
    const clearSelectionAndControls = () => {
        if (selectedRow) {
            selectedRow.classList.remove('selected-row');
            selectedRow = null;
        }
        document.getElementById('row-controls').innerHTML = '';
    };

    // Inicializar el contenedor de controles si no existe
    let controlsContainer = document.getElementById('row-controls');
    if (!controlsContainer) {
        controlsContainer = document.createElement('div');
        controlsContainer.id = 'row-controls';
        controlsContainer.style.marginTop = '20px';
        controlsContainer.style.padding = '15px';
        controlsContainer.style.border = '1px solid #ccc';
        controlsContainer.style.borderRadius = '4px';
        document.getElementById('spreadsheet-container').insertAdjacentElement('afterend', controlsContainer);
    }


    // Event Listener para la selección de filas
    rowHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const rowNumber = this.dataset.row;
            const targetRow = document.querySelector(`tbody tr[data-row="${rowNumber}"]`);

            if (targetRow && targetRow !== selectedRow) {
                clearSelectionAndControls();
                selectedRow = targetRow;
                selectedRow.classList.add('selected-row');
                console.log(`Fila ${rowNumber} seleccionada.`);
                displayControls(targetRow);
            } else if (!targetRow) {
                 // Si la fila no existe (seguridad), limpiamos y salimos.
                clearSelectionAndControls();
            }
        });
    });

    /**
     * Muestra los controles de acción basados en la fila seleccionada.
     * @param {HTMLElement} row - La fila <tr> que ha sido seleccionada.
     */
    const displayControls = (row) => {
        const controlsContainer = document.getElementById('row-controls');
        if (!controlsContainer) return;

        // Limpiar controles anteriores y agregar nuevos botones
        controlsContainer.innerHTML = `
            <button id="btn-clear-content" class="action-btn">🗑️ Vaciar Contenido</button>
            <button id="btn-change-color" class="action-btn">🎨 Cambiar Color Fondo</button>
            <button id="btn-delete-row" class="action-btn delete-btn">❌ Borrar Fila Completa</button>
        `;

        // Asignar listeners a los nuevos botones
        document.getElementById('btn-clear-content').addEventListener('click', () => {
            const cells = row.querySelectorAll('td');
            cells.forEach(cell => cell.textContent = '');
        });

        document.getElementById('btn-change-color').addEventListener('click', () => {
            // Cambia el color de fondo de TODAS las celdas (incluyendo la columna A que es th)
            row.querySelectorAll('th, td').forEach(cell => {
                cell.style.backgroundColor = '#ffebcc'; // Un amarillo claro para indicar cambio
            });
        });

        document.getElementById('btn-delete-row').addEventListener('click', () => {
            if (confirm(`¿Está seguro de que desea borrar la fila ${selectedRow.dataset.row}? Esta acción es irreversible.`)) {
                // Borrar el elemento <tr> completo
                selectedRow.remove();
                clearSelectionAndControls();
                alert("Fila borrada con éxito.");
            }
        });
    };

    // Listener global para deseleccionar y limpiar controles cuando se hace clic fuera de la hoja
    document.body.addEventListener('click', (e) => {
        if (!e.target.closest('#spreadsheet-grid') && !e.target.closest('.row-header')) {
            clearSelectionAndControls();
        }
    });
}
