### FUNCION: initializeRowSelectionAndControls
```js
/**
 * Inicializa la funcionalidad de selección y manipulación de filas.
 * Permite seleccionar una fila haciendo clic en su número de encabezado, 
 * y luego realizar acciones como borrar contenido, cambiar color o eliminar la fila.
 */
function initializeRowSelectionAndControls() {
    const rowHeaders = document.querySelectorAll('.row-header');
    let selectedRowElement = null;

    // 1. Manejador de Selección de Fila (Clic en el número)
    const handleRowClick = (e) => {
        const header = e.currentTarget;
        const rowIndex = header.dataset.row;
        const rowCells = document.querySelectorAll(`[data-row="${rowIndex}"]`);

        // Deseleccionar cualquier fila previamente seleccionada
        if (selectedRowElement) {
            selectedRowElement.classList.remove('selected-row');
        }

        // Seleccionar la nueva fila
        header.classList.add('selected-row');
        selectedRowElement = header;
    };

    rowHeaders.forEach(header => {
        header.addEventListener('click', handleRowClick);
    });


    // 2. Funcionalidad para borrar contenido de una fila seleccionada
    const clearSelectedRowContent = () => {
        if (!selectedRowElement) {
            alert("Por favor, seleccione una fila primero.");
            return;
        }

        // Encontrar la fila completa (el <tr> padre) del encabezado seleccionado
        const row = selectedRowElement.closest('tr');
        if (!row) return;

        // Seleccionar todas las celdas de datos (<td>) dentro de esa fila
        const dataCells = row.querySelectorAll('td');

        dataCells.forEach(cell => {
            cell.textContent = ''; // Borrar contenido
            cell.style.backgroundColor = ''; // Limpiar color de fondo
        });
    };


    // 3. Funcionalidad para cambiar el color de fondo de una fila seleccionada
    const changeSelectedRowColor = () => {
        if (!selectedRowElement) {
            alert("Por favor, seleccione una fila primero.");
            return;
        }

        const row = selectedRowElement.closest('tr');
        if (!row) return;

        // Aplicar color de fondo a todas las celdas de datos (<td>)
        const dataCells = row.querySelectorAll('td');
        dataCells.forEach(cell => {
            cell.style.backgroundColor = '#fffacd'; // Color pastel claro para simular selección/resaltado
        });

         // También resaltamos el encabezado de la fila seleccionada
        selectedRowElement.style.backgroundColor = 'rgba(0, 123, 255, 0.1)';

    };


    // 4. Funcionalidad para borrar completamente una fila (elemento <tr>)
    const deleteSelectedRow = () => {
        if (!selectedRowElement) {
            alert("Por favor, seleccione la fila que desea eliminar.");
            return;
        }

        if (!confirm("¿Está seguro de que desea eliminar esta fila completa? Esta acción es irreversible.")) {
            return;
        }

        const rowToDelete = selectedRowElement.closest('tr');
        if (rowToDelete) {
            // Eliminar la fila del DOM
            rowToDelete.remove();
            selectedRowElement = null; // Resetear el estado de selección
            alert("Fila eliminada exitosamente.");
        }
    };

    // 5. Asignar listeners a los botones de control (se asume que existen en index.html)
    const clearBtn = document.getElementById('clear-row-btn');
    const colorBtn = document.getElementById('color-row-btn');
    const deleteBtn = document.getElementById('delete-row-btn');

    if (clearBtn) {
        clearBtn.addEventListener('click', clearSelectedRowContent);
    }
    if (colorBtn) {
        colorBtn.addEventListener('click', changeSelectedRowColor);
    }
    if (deleteBtn) {
        deleteBtn.addEventListener('click', deleteSelectedRow);
    }
}
```

