### FUNCION: handleRowSelection
```js
function handleRowSelection(e) {
    const rowElement = e.currentTarget;
    const rowNumber = rowElement.dataset.row;
    if (!rowNumber) return;

    // 1. Deseleccionar cualquier fila previamente seleccionada
    document.querySelectorAll('.row-header').forEach(th => {
        th.style.backgroundColor = ''; // Limpiar color de fondo
        th.removeAttribute('data-selected');
    });

    // 2. Seleccionar la nueva fila y actualizar el estado visual
    rowElement.style.backgroundColor = '#e0f7fa'; // Color suave para indicar selección
    rowElement.setAttribute('data-selected', 'true');

    // 3. Actualizar los controles de acción
    document.getElementById('selected-row-display').textContent = rowNumber;
    const controlsPanel = document.getElementById('row-actions');
    controlsPanel.style.display = 'block';

    // Habilitar botones y configurar el picker de color
    document.getElementById('clear-row-content-btn').disabled = false;
    document.getElementById('delete-row-btn').disabled = false;

    const currentColor = getComputedStyle(rowElement).backgroundColor;
    document.getElementById('bg-color-picker').value = rgbToHex(currentColor); // Intentar preseleccionar el color actual
}

// Helper function to convert RGB color string (e.g., rgba(255, 0, 0, 1)) to Hex
function rgbToHex(rgb) {
    if (!rgb || !rgb.includes('rgb')) return '#ffffff';
    const rgbMatch = rgb.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    if (!rgbMatch) return '#ffffff';
    const r = parseInt(rgbMatch[1]).toString(16).padStart(2, '0');
    const g = parseInt(rgbMatch[2]).toString(16).padStart(2, '0');
    const b = parseInt(rgbMatch[3]).toString(16).padStart(2, '0');
    return '#' + r + g + b;
}

// Helper function to get all data cells in the row (excluding the header cell itself)
function getCellsInSelectedRow() {
    const selectedHeader = document.querySelector('.row-header[data-selected="true"]');
    if (!selectedHeader) return [];

    const row = selectedHeader.closest('tr');
    // Seleccionamos todos los <td> dentro de la fila (excluyendo el <th> header)
    return Array.from(row.querySelectorAll('td'));
}
