    const dataCells = selectedRow.querySelectorAll('td[contenteditable="true"]');
    dataCells.forEach(cell => cell.blur()); // Fuerza la pérdida de foco para detener cálculos o ediciones parciales

    // 5. Mostrar el menú contextual/acciones (simulando la aparición de controles)
    showContextMenu(e, selectedRow);
}

/**
 * Muestra un menú simulado con acciones disponibles en la fila seleccionada.
 */
function showContextMenu(e, rowElement) {
    // Prevenir el menú nativo del navegador al hacer clic derecho
    e.preventDefault(); 

    const menu = document.getElementById('row-context-menu');
    if (!menu) return;

