    menu.style.display = 'block';
    const menuBounds = getComputedStyle(menu).getPropertyValue('--menu-width');
    const menuOffsetTop = Math.min(e.clientY - 150, window.innerHeight * 0.8); // Limita arriba
    const menuOffsetLeft = Math.min(e.clientX, window.innerWidth - (parseFloat(menuBounds) || 200)); // Limita derecha

    menu.style.left = `${menuOffsetLeft}px`;
    menu.style.top = `${menuOffsetTop}px`;
}


/**
 * Inicializa listeners en todos los encabezados de fila para permitir la selección y las acciones contextuales.
 */
function initializeRowHeaderListeners() {
    const rowHeaders = document.querySelectorAll('.row-header');

    if (rowHeaders.length === 0) return;

    // Añadir listener de clic derecho para seleccionar la fila y mostrar controles
    rowHeaders.forEach(header => {
        header.addEventListener('contextmenu', handleRowSelection);
    });
}


/**
 * Función principal que arranca la aplicación
 */
function startApp() {
    initializeCellEditing();
    // Inicializar los listeners de selección de filas al cargar la app
    initializeRowHeaderListeners();
}

startApp();
