/**
 * Configura los listeners en los encabezados de columna y fila para permitir ocultar/mostrar dimensiones.
 */
function setupHeaderInteractions() {
    const columnHeaders = document.querySelectorAll('#spreadsheet-grid .col-header');
    const rowHeaders = document.querySelectorAll('#spreadsheet-grid .row-header');

    // Listener para encabezados de columna (A, B, C...)
    columnHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const columnName = this.dataset.column;
            if (!columnName) return;

            let allCells = document.querySelectorAll(`td[data-cell^="${columnName}"]`);
            let isHidden = Array.from(allCells).some(cell => cell.style.display === 'none');

            // Toggle visibility for data cells and the column header itself
            allCells.forEach(cell => {
                if (isHidden) {
                    cell.style.display = ''; // Mostrar
                } else {
                    cell.style.display = 'none'; // Ocultar
                }
            });

            // Toggle visibility for the column letter header in <thead>
            this.style.display = isHidden ? '' : 'none';
        });
    });

    // Listener para encabezados de fila (1, 2, 3...)
    rowHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const rowNumber = this.dataset.row;
            if (!rowNumber) return;

            // Objetivo: el <tr> completo en tbody que corresponde a esta fila
            const targetRow = document.querySelector(`tbody tr[data-row="${rowNumber}"]`);
            if (!targetRow) return;

            let isHidden = targetRow.style.display === 'none';

            // Toggle visibility for the entire row
            targetRow.style.display = isHidden ? '' : 'none';
        });
    });
}
