```js
/**
 * Configura los listeners para las cabeceras de columna y fila, permitiendo ocultarlas o mostrarlas.
 */
function setupHeaderInteractions() {
    const headers = document.querySelectorAll('.col-header');
    const rowHeaders = document.querySelectorAll('.row-header');

    // --- Lógica de Ocultar/Mostrar Columnas ---
    headers.forEach(header => {
        header.addEventListener('click', function() {
            const colLetter = this.dataset.column;
            if (!colLetter) return;

            let isCurrentlyHidden = this.classList.contains('hidden-col'); 

            // Toggle state visual (esto ayuda a saber si lo que hicimos fue un show o hide)
            this.classList.toggle('hidden-col'); 

            const allRows = document.querySelectorAll('#spreadsheet-grid tbody tr');

            allRows.forEach(row => {
                // Buscamos la celda correspondiente a esta columna en todas las filas de datos
                // Nota: Usamos data-cell^ para encontrar el patrón (Ej: A1, A2...)
                const colCell = row.querySelector(`[data-cell*="${colLetter}"]`); 
                if (colCell) {
                    if (isCurrentlyHidden) {
                        colCell.style.display = ''; // Mostrar
                    } else {
                        colCell.style.display = 'none'; // Ocultar
                    }
                }
            });
        });
    });

    // --- Lógica de Ocultar/Mostrar Filas ---
    rowHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const rowNumber = this.dataset.row;
            if (!rowNumber) return;

            let isCurrentlyHidden = this.classList.contains('hidden-row');

            // Toggle state visual para la cabecera de fila
            this.classList.toggle('hidden-row'); 

            // Buscamos la fila completa usando el atributo data-row en el tbody
            const targetRow = document.querySelector(`#spreadsheet-grid tbody tr[data-row="${rowNumber}"]`);
            if (targetRow) {
                if (isCurrentlyHidden) {
                    targetRow.style.display = ''; // Mostrar
                } else {
                    targetRow.style.display = 'none'; // Ocultar
                }
            }
        });
    });
}
