function handleHeaderContextMenu(e) {
    e.preventDefault(); // Prevent default context menu
    const header = e.currentTarget;
    let rowNum = null;
    let colLetter = null;

    // Determine if we are on a Row Header or Column Header
    if (header.classList.contains('row-header')) {
        rowNum = header.dataset.row;
        colLetter = null; // Not relevant for hiding rows
    } else if (header.classList.contains('col-header')) {
        rowNum = null; // Not relevant for hiding columns
        colLetter = header.dataset.column;
    }

    // Create and position the context menu
    const menu = document.createElement('div');
    menu.className = 'context-menu';
    menu.innerHTML = `
        <div class="menu-item" data-action="hide">Ocultar</div>
        <div class="menu-separator"></div>
        <div class="menu-item" data-action="show">Mostrar</div>
    `;

    // Calculate position relative to the viewport and mouse coordinates
    const rect = header.getBoundingClientRect();
    menu.style.top = `${e.clientY - 20}px`; // Offset slightly above cursor
    menu.style.left = `${e.clientX}px`;

    document.body.appendChild(menu);

    // Attach listeners to the menu items
    const items = menu.querySelectorAll('.menu-item');
    items.forEach(item => {
        item.addEventListener('click', (event) => {
            const action = event.target.dataset.action;
            if (!action) return;

            // Hide the context menu immediately after selection
            document.body.removeChild(menu);

            if (action === 'hide') {
                if (header.classList.contains('row-header')) {
                    hideRow(parseInt(rowNum));
                } else if (header.classList.contains('col-header')) {
                    hideColumn(colLetter);
                }
            } else if (action === 'show') {
                if (header.classList.contains('row-header')) {
                    showRow(parseInt(rowNum));
                } else if (header.classList.contains('col-header')) {
                    showColumn(colLetter);
                }
            }
        });
    });

    // Global click listener to remove the menu if clicking outside
    document.addEventListener('click', function handler(e) {
        if (!menu.contains(e.target)) {
            document.body.removeChild(menu);
            document.removeEventListener('click', handler); // Clean up event listener
        }
    });
}
