function hideColumn(columnLetter) {
    const colHeader = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (colHeader) {
        // En la tabla, las columnas están contenidas en <th> o <td> de la cabecera/cuerpo.
        // Para ocultar una columna completamente, debemos iterar sobre todas las celdas que corresponden a esa letra y ocultarlas.

        // 1. Ocultar el header de la columna (A-J)
        colHeader.style.display = 'none';

        // 2. Iterar sobre todas las filas de datos para ocultar el contenido de esa celda en cada fila.
        const dataCells = document.querySelectorAll('#spreadsheet-grid td[data-cell*="'+columnLetter+'"]');

        if (dataCells.length === 0) {
             console.warn(`No se encontraron celdas para la columna ${columnLetter}.`);
             return;
        }

        // La forma más robusta es ocultar todas las celdas con ese atributo data-cell
        // Esto asume que el selector de datos está en el tbody o similar, pero dado que estamos usando <table id="spreadsheet-grid">, 
        // debemos ser más específicos y afectar a todos los td.

        const allRows = document.querySelectorAll('#spreadsheet-grid tbody tr');
        allRows.forEach(row => {
            // Buscar la celda específica de esta columna en el fondo (td) de esa fila
            const cellToHide = row.querySelector(`[data-cell*="${columnLetter}"]`);
            if (cellToHide) {
                cellToHide.style.display = 'none';
            }
        });

        console.log(`Columna ${columnLetter} oculta.`);
    }
}
