### FUNCION: hideOrUnhideColumn
```javascript
function hideOrUnhideColumn(headerCell, columnIndex) {
    // headerCell is the <th> in thead for the column letter (e.g., A)
    // The actual index calculation is relative to the table body structure.

    const allCells = document.querySelectorAll('#spreadsheet-grid td');
    let visibleCount = 0;

    // 1. Toggle visibility of the header cell itself
    if (headerCell.style.display === 'none') {
        headerCell.style.display = '';
    } else {
        headerCell.style.display = 'none';
    }

    // 2. Iterate through all rows to toggle the display of data cells in this column index
    allCells.forEach((cell, index) => {
        // We skip the first cell (the row-header cell), so we check if the current cell's position matches the target column index + 1
        // Data cells start after the row header cell (index > 0).
        if (!cell.parentElement || !cell.parentElement.rowIndex) return;

        const row = cell.closest('tr');
        const colIndexInRow = Array.from(row.querySelectorAll('td')).indexOf(cell);

        // Check if this cell belongs to the column we are manipulating (colIndexInRow must match columnIndex)
        if (colIndexInRow === columnIndex) {
            if (cell.style.display === 'none') {
                cell.style.display = ''; // Show the cell
                visibleCount++;
            } else {
                cell.style.display = 'none'; // Hide the cell
            }
        }
    });

    // Update row count displayed in row headers if necessary (optional, but good practice)
    updateRowHeaders();
}
