```javascript
/**
 * Inicializa la funcionalidad de edición inline en todas las celdas de datos.
 */
function initializeCellEditing() {
    // Helper function to get value from a given coordinate (e.g., 'A1')
    const getValue = (coordinate) => {
        const cell = document.querySelector(`td[data-cell="${coordinate}"]`);
        if (!cell) return null;

        let text = cell.textContent.trim();
        // Attempt to parse as float if it looks like a number, otherwise use the string.
        return isNaN(parseFloat(text)) ? text : parseFloat(text);
    };

    // Helper function to calculate formulas based on Excel rules (SUMA, +, -, *, /)
    const evaluateFormula = (formulaString) => {
        try {
            let formula = formulaString.toUpperCase();
            if (!formula.startsWith('=')) return null;
            formula = formula.substring(1); // Remove '='

            // --- 1. SUMA Range (e.g., SUMA(A1:A3)) ---
            const sumMatch = formula.match(/SUMA\((.*)\)/);
            if (sumMatch) {
                let rangeString = sumMatch[1]; // e.g., A1:A3

                // Basic parsing for ranges assuming they are single column contiguous ranges (like A1:A3)
                const coords = rangeString.split(':').map(s => s.trim());
                if (coords.length !== 2 || !coords[0] || !coords[1]) return null;

                let startCoord = coords[0]; // e.g., A1
                let endCoord = coords[1];   // e.g., A3

                const startCol = startCoord[0].toUpperCase();
                const startRow = parseInt(startCoord.substring(1));
                const endRow = parseInt(endCoord.substring(1));

                if (!startCol || isNaN(startRow) || isNaN(endRow)) return null;

                let total = 0;
                for (let r = Math.min(startRow, endRow); r <= Math.max(startRow, endRow); r++) {
                    const cellValue = getValue(`${startCol}${r}`);
                    if (cellValue !== null && typeof cellValue === 'number') {
                        total += cellValue;
                    } else if (typeof cellValue === 'string' && !isNaN(parseFloat(cellValue))) {
                         // Handle case where text content might be a number string
                         total += parseFloat(cellValue);
                    }
                }
                return total;
            }

            // --- 2. Simple Operations (A1-B1, A1*B1, etc.) ---
            let expression = formula;

            // Replace coordinates with numeric values for evaluation
            expression = expression.replace(/([A-Z]+[0-9]+)/g, (match) => {
                const value = getValue(match);
                return typeof value === 'number' ? value : parseFloat(value) || 0; // Use number or default to 0
            });

            // Evaluate the resulting mathematical string expression
            if (!isNaN(parseFloat(expression))) {
                // Using Function constructor for safe evaluation of arithmetic expressions in this controlled scope.
                return new Function('return ' + expression)();
            }

        } catch (e) {
            console.error("Error evaluating formula:", e);
            return null;
        }
        return null; // Calculation failed or unsupported formula type
    };


    // Selecciona todas las celdas de datos que son editables.
    const dataCells = document.querySelectorAll('#spreadsheet-grid td[contenteditable="true"]');

    dataCells.forEach(cell => {
        // Añadimos un listener 'blur' (cuando se pierde el foco) para simular la finalización de la edición y calcular fórmulas.
        cell.addEventListener('blur', function() {
            let content = this.textContent.trim();
            let calculatedValue = null;

            if (content.startsWith('=')) {
                // Intentar evaluar fórmula
                calculatedValue = evaluateFormula(content);

                // Si la evaluación fue exitosa y resultó en un número, actualizamos el contenido de la celda.
                if (typeof calculatedValue === 'number' && !isNaN(calculatedValue)) {
                    this.textContent = calculatedValue; // Mostrar resultado numérico
                } else {
                    // Si falla o no es una fórmula manejada, lo dejamos como texto original.
                    console.warn(`No se pudo calcular la fórmula en ${this.dataset.cell}: ${content}`);
                }

            } else {
                 // Limpiamos el contenido si era solo un valor numérico sin formato de celda
                 this.textContent = content;
            }
        });

        // Opcionalmente, un listener 'focus' para resaltar visualmente la celda al hacer clic en cualquier parte del documento (fuera de las celdas).
    });


    // --- NUEVO MANEJADOR DE EVENTOS PARA ENCABEZADOS Y ACCIONES ---

    const headers = document.querySelectorAll('.col-header, .row-header');
    headers.forEach(header => {
        const isColHeader = header.classList.contains('col-header');

        // 1. Manejo de clics en el menú '...' (Acciones)
        const actionMenu = header.querySelector('.action-menu');
        if (actionMenu) {
            actionMenu.addEventListener('click', (e) => {
                e.stopPropagation(); // Prevenir que se dispare el evento del body click
                showContextMenu(header, isColHeader);
            });
        }

        // 2. Manejo de clics en los encabezados para ocultar/mostrar directamente
        header.addEventListener('click', (e) => {
             // Si hizo clic en el menú '...', ya se manejó arriba y no queremos que dispare más cosas.
            if (!e.target.closest('.action-menu')) {
                const isColHeader = header.classList.contains('col-header');
                 if (isColHeader) {
                    // Si hace clic directamente en el encabezado, mostramos un menú de acciones para ser consistente.
                    showContextMenu(header, true);
                } else {
                    // Si es row-header, o si ya se mostró el menú y no hizo click en '...'
                    const isRowHeader = header.classList.contains('row-header');
                    if (isRowHeader) {
                         showContextMenu(header, false);
                    }
                }
            }
        });

    });


    // Listener global para limpiar el foco visual y los menús de acción cuando se haga clic en cualquier parte del documento.
    document.body.addEventListener('click', function(e) {
        // Limpiar focus de celdas de datos
        if (!e.target.closest('[contenteditable="true"]')) {
            dataCells.forEach(c => c.classList.remove('focused-cell'));
        }

        // Ocultar cualquier menú contextual abierto
        document.querySelectorAll('.context-menu').forEach(menu => menu.remove());
        document.querySelectorAll('.action-menu').forEach(menu => menu.setAttribute('data-visible', 'false'));
    });
}

/**
 * Muestra el menú de acciones contextual al hacer clic en un header.
 * @param {HTMLElement} targetHeader - El elemento <th> (row o col).
 * @param {boolean} isColHeader - True si es una columna, False si es una fila.
 */
function showContextMenu(targetHeader, isColHeader) {
    let menu = document.querySelector('.context-menu');
    if (!menu) {
        menu = document.createElement('div');
        menu.className = 'context-menu';
        document.body.appendChild(menu);
    }

    // Limpiar contenido anterior
    menu.innerHTML = '';

    const actionsDiv = document.createElement('div');
    actionsDiv.style.position = 'absolute';
    actionsDiv.style.top = `${targetHeader.getBoundingClientRect().top + targetHeader.offsetHeight / 2 - 5}px`;
    actionsDiv.style.left = `${targetHeader.getBoundingClientRect().left + targetHeader.offsetWidth - 10}px`;

    if (isColHeader) {
        const colName = targetHeader.dataset.column;
        const title = `Acciones Columna ${colName}`;
        actionsDiv.innerHTML = `<strong>${title}</strong><button id="hide-col">Ocultar Columna</button><button id="show-col">Mostrar Columna</button>`;
    } else {
        const rowNum = targetHeader.dataset.row;
        const title = `Acciones Fila ${rowNum}`;
        actionsDiv.innerHTML = `<strong>${title}</strong><button id="hide-row">Ocultar Fila</button><button id="show-row">Mostrar Fila</button>`;
    }

    // Agregar el menú al body (o un contenedor superior) para que se posicione correctamente
    document.body.appendChild(actionsDiv); 
    menu = actionsDiv; // Reasignamos 'menu' a la nueva acción de accionesDiv

    // Posicionar y mostrar
    menu.style.display = '';
    setTimeout(() => {
        menu.style.opacity = Math.max(0, parseFloat(getComputedStyle(targetHeader).opacity) * 1); // Forcing reflow/repaint
        menu.querySelector('button').focus();
    }, 10);


    // Event Listeners para las acciones del menú
    const hideButton = menu.querySelector('#hide-col') || menu.querySelector('#hide-row');
    const showButton = menu.querySelector('#show-col') || menu.querySelector('#show-row');

    if (hideButton) {
        hideButton.onclick = () => {
            if (isColHeader) {
                // Column index is 0 for A, 1 for B, etc.
                const colIndex = targetHeader.dataset.column.charCodeAt(0) - 'A'.charCodeAt(0);
                hideOrUnhideColumn(targetHeader, colIndex);
            } else {
                // Row element itself (the TR)
                const rowElement = targetHeader.closest('tr');
                if (rowElement) {
                    hideOrUnhideRow(rowElement);
                }
            }
        };
    }

    if (showButton) {
        showButton.onclick = () => {
             if (isColHeader) {
                const colIndex = targetHeader.dataset.column.charCodeAt(0) - 'A'.charCodeAt(0);
                hideOrUnhideColumn(targetHeader, colIndex);
            } else {
                // Row element itself (the TR)
                const rowElement = targetHeader.closest('tr');
                if (rowElement) {
                    // Mostrar la fila si estaba oculta. 
                    // Nota: Aquí no podemos rellenar el contenido automáticamente, solo mostramos la estructura.
                     hideOrUnhideRow(rowElement);
                }
            }
        };
    }

    // Función para limpiar el menú al hacer clic fuera de él
    document.addEventListener('click', function(e) {
        if (!menu.contains(e.target)) {
            menu.style.display = 'none';
            menu.innerHTML = ''; // Limpiar botones y contenido
        }
    });
}


// Función principal que arranca la aplicación
function startApp() {
    initializeCellEditing();
}

startApp();
